/// `LANGUAGE_EXTENSION_ALIASES`.
fn language_extension(key: &str) -> Option<&'static str> {
    Some(match key {
        "bash" => "sh",
        "csharp" => "cs",
        "elixir" => "ex",
        "haskell" => "hs",
        "javascript" => "js",
        "jsx" => "jsx",
        "kotlin" => "kt",
        "markdown" => "md",
        "mdx" => "mdx",
        "plaintext" => "txt",
        "powershell" => "ps1",
        "python" => "py",
        "ruby" => "rb",
        "rust" => "rs",
        "shell" => "sh",
        "shellscript" => "sh",
        "swift" => "swift",
        "typescript" => "ts",
        "tsx" => "tsx",
        "yaml" => "yml",
        _ => return None,
    })
}

/// `LANGUAGE_FILE_NAMES`.
fn language_file_name(key: &str) -> Option<&'static str> {
    Some(match key {
        "dockerfile" => "Dockerfile",
        _ => return None,
    })
}

